using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Returns the current server time in UTC.")]
    public static string GetServerTime() =>
        DateTime.UtcNow.ToString("o");

    [McpServerTool, Description("Echoes back the provided message, useful for testing connectivity.")]
    public static string Echo(
        [Description("The message to echo back")] string message) =>
        $"Echo: {message}";
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ServerResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppConfig() =>
        JsonSerializer.Serialize(new
        {
            version = "1.0.0",
            environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            features = new { caching = true, rateLimit = 100 },
            supportedRegions = new[] { "us-east", "eu-west", "ap-southeast" }
        }, new JsonSerializerOptions { WriteIndented = true });

    [McpServerResource(
        UriTemplate = "config://status",
        Name = "Server Status",
        MimeType = "application/json"),
     Description("Returns the current server status and uptime info.")]
    public static string GetServerStatus() =>
        JsonSerializer.Serialize(new
        {
            status = "healthy",
            startedAt = System.Diagnostics.Process.GetCurrentProcess().StartTime.ToUniversalTime(),
            machineName = Environment.MachineName
        }, new JsonSerializerOptions { WriteIndented = true });
}

